Значения будут отражены в последующих вызовах из того же метода.

Пример:

    package main

    import "fmt"

    type demo struct {
     Val int
    }

    func (d *demo) change() {
     d = nil // Присвоение приемнику метода распространяется только на вызываемых, но не на вызывающих
     d.myVal()
    }

    func (d *demo) myVal() {
     fmt.Printf("my val: %#v\n", d)
    }

    func (d demo) change2() {
     d = demo{} // Присвоение приемнику метода не распространяется на другие вызовы
     d.myVal()
    }

    func (d *demo) change3() {
     d.Val = 3
     d.myVal()
    }

    func main() {
     d := &demo{}
     d.myVal()
     d.change()
     d.myVal()
     d.Val = 2
     d.change2()
     d.myVal()
     d.change3()
